import{_ as e,o as r,c as a,a6 as o}from"./chunks/framework.BBdhcoHf.js";const y=JSON.parse('{"title":"Protocol Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"protocols/glossary.md","filePath":"protocols/glossary.md","lastUpdated":1772116603000}'),d={name:"protocols/glossary.md"};function i(n,t,s,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /protocols/glossary.md for this page in Markdown format</div><h1 id="protocol-glossary" tabindex="-1">Protocol Glossary <a class="header-anchor" href="#protocol-glossary" aria-label="Permalink to “Protocol Glossary”">​</a></h1><blockquote><p><strong>Authority</strong>: Supporting (Reference)<br><strong>Purpose</strong>: Canonical definitions for cross-protocol terminology.</p></blockquote><p>Terms defined here are authoritative. Protocol-specific index.md files SHOULD link here and MAY include a Local Terminology section for protocol-scoped terms.</p><h2 id="identity-session" tabindex="-1">Identity &amp; Session <a class="header-anchor" href="#identity-session" aria-label="Permalink to “Identity &amp; Session”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>PeerId</td><td>Stable identity of a peer node; survives reconnects</td></tr><tr><td>SessionId</td><td>8-byte identifier for a relay session (SBRP); bound to token claims</td></tr><tr><td>FrameId</td><td>16 opaque bytes identifying a frame instance on wire</td></tr><tr><td>ConnectionId</td><td>Transient transport link identity; new per TCP/WebSocket</td></tr></tbody></table><h2 id="cryptographic" tabindex="-1">Cryptographic <a class="header-anchor" href="#cryptographic" aria-label="Permalink to “Cryptographic”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>TOFU</td><td>Trust-On-First-Use identity pinning; client pins daemon public key on first connection</td></tr><tr><td>Identity Key</td><td>Long-lived Ed25519 keypair for daemon authentication</td></tr><tr><td>Ephemeral Key</td><td>Per-session X25519 keypair for key exchange</td></tr><tr><td>Session Key</td><td>Derived HKDF key for symmetric encryption</td></tr><tr><td>Replay Window</td><td>Bitmap-based sliding window for sequence validation</td></tr></tbody></table><h2 id="framing" tabindex="-1">Framing <a class="header-anchor" href="#framing" aria-label="Permalink to “Framing”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>Frame</td><td>Protocol data unit with header + payload; see FrameKind for variants</td></tr><tr><td>FrameKind</td><td>Discriminant enum: Control, Message, Ack, Error (SBP) or frame types (SBRP)</td></tr><tr><td>Envelope</td><td>RPC structure inside MessageFrame.data; see RPC envelope spec</td></tr><tr><td>Payload</td><td>Frame body after the header; semantics depend on frame type</td></tr></tbody></table><h2 id="protocol-layers" tabindex="-1">Protocol Layers <a class="header-anchor" href="#protocol-layers" aria-label="Permalink to “Protocol Layers”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>SBP</td><td>Sideband Protocol - topology-agnostic application framing</td></tr><tr><td>SBRP</td><td>Sideband Relay Protocol - E2EE sessions via relay server</td></tr><tr><td>SBDP</td><td>Sideband Direct Protocol - P2P sessions (future)</td></tr><tr><td>RPC</td><td>Request/response/notification semantics inside SBP MessageFrame</td></tr></tbody></table><h2 id="sbrp-specific" tabindex="-1">SBRP-Specific <a class="header-anchor" href="#sbrp-specific" aria-label="Permalink to “SBRP-Specific”">​</a></h2><table tabindex="0"><thead><tr><th>Term</th><th>Definition</th></tr></thead><tbody><tr><td>Relay</td><td>Routing authority and token validator; not an encryption endpoint</td></tr><tr><td>Client</td><td>Session initiator with ephemeral keys; no persistent crypto identity</td></tr><tr><td>Daemon</td><td>Long-lived agent with Ed25519 identity; reachable via relay</td></tr><tr><td>Control Frame (SBRP)</td><td>Relay-generated notifications (0x20); distinct from SBP ControlFrame</td></tr><tr><td>Signal Frame</td><td>Daemon-to-relay session lifecycle commands (ready/close)</td></tr><tr><td>Nonce Monotonicity</td><td>Sequence numbers must strictly increase per direction</td></tr><tr><td>Throttling</td><td>Traffic control category (0x09xx); covers rate-limiting (non-terminal: back off and retry) and backpressure (terminal: slow consumer closed)</td></tr><tr><td>Backpressure</td><td>Terminal relay signal (0x0902) closing a connection whose send buffer is full; distinct from <code>rate_limited</code> (0x0901) which is non-terminal</td></tr></tbody></table>',14)])])}const m=e(d,[["render",i]]);export{y as __pageData,m as default};
